cypress_script:
describe('Broken Images Page', () => {
  it('should display the heading and footer correctly', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.contains('Broken Images').should('be.visible');
    cy.contains('Powered by Elemental Selenium').should('be.visible');
  });
  it('should not find any images on the page', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('#content').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Broken Images Page', () => {
  test('should display the heading and footer correctly', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    await expect(page.locator('text=Broken Images')).toBeVisible();
    await expect(page.locator('text=Powered by Elemental Selenium')).toBeVisible();
  });
  test('should not find any images on the page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    await expect(page.locator('#content')).toBeVisible();
  });
});
